L6: /** Bindable command id for opening the scratchpad in the user's editor. */
L7: export const EDITOR_COMMAND_ID = "opencode-scratchpad.editor";
L8: 
L9: /** The renderer controls the external editor session needs. */
L10: export interface RendererControl {
L11:   suspend(): Promise<void>;
L12:   resume(): Promise<void>;
L13:   requestRender(): void;
L14: }
L15: 
L16: /** Arguments handed to the process that launches the user's editor. */
L17: export interface EditorRunArgs {
L18:   command: string;
L19:   file: string;
L20:   cwd: string | undefined;
L21: }
L22: 
L23: export interface ExternalEditorOptions {
L24:   value: string;
L25:   env?: Record<string, string | undefined>;
L26:   cwd?: string;
L27:   renderer?: RendererControl | null;
L28:   tmpDir?: string;
L29:   now?: () => number;
L30:   runEditor?: (args: EditorRunArgs) => Promise<void>;
L31: }
L32: 
L33: /** Resolves the editor command from `$VISUAL`, falling back to `$EDITOR`. */
L34: export function resolveEditorCommand(
L35:   env: Record<string, string | undefined> = process.env,
L36: ): string | undefined {
L37:   const raw = env.VISUAL?.trim() || env.EDITOR?.trim();
L38:   return raw && raw.length > 0 ? raw : undefined;
L39: }
L40: 
L41: /** Spawns the editor on `file`, resolving once it exits cleanly. */
L42: async function defaultRunEditor({ command, file, cwd }: EditorRunArgs): Promise<void> {
L43:   const parts = command.split(" ");
L44:   const bin = parts[0]!;
L45:   const args = [...parts.slice(1), file];
L46: 
L47:   await new Promise<void>((resolve, reject) => {
L48:     const child = spawn(bin, args, {
L49:       cwd: cwd && fs.existsSync(cwd) ? cwd : process.cwd(),
L50:       stdio: ["inherit", "inherit", "inherit"],
L51:       shell: process.platform === "win32",
L52:     });
L53: 
L54:     child.on("error", reject);
L55:     child.on("exit", (code, signal) => {
L56:       if (code === 0) {
L57:         resolve();
L58:         return;
L59:       }
L60:       reject(
L61:         new Error(
L62:           `Editor exited with ${signal ? `signal ${signal}` : `code ${code}`}`,
L63:         ),
L64:       );
L65:     });
L66:   });
L67: }
L68: 
